#!/usr/bin/env python3
"""Build a bounded home-page patch from byte-verified production snapshots.

The old preview templates are not the current production source. This recipe
preserves the deployed IT/EN content and only changes the listed performance resources.
"""
import argparse
import hashlib
import json
from html.parser import HTMLParser
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]
WORK = ROOT / '.github/cad3d-live'
BASE = WORK / 'baseline/20261026'
OUTPUT = WORK / 'payload'
PREFIX = '/_cad3d-site/assets/'
IMAGES = {
    'villa-ai-v4-small.webp': 'villa-preview-880-p1.webp',
    'bath-blue-ai-v4-small.webp': 'bath-preview-880-p1.webp',
    'film-interior-poster-v5.webp': 'film-interior-poster-p1.webp',
    'film-detail-poster-v5.webp': 'film-detail-poster-p1.webp',
    'interior-scene7-20261023.png': 'interior-scene7-thumb-p1.webp',
}


class Content(HTMLParser):
    def __init__(self):
        super().__init__()
        self.text, self.links, self.ids, self.images, self.meta = [], [], [], [], []

    def handle_data(self, data):
        if data.strip():
            self.text.append(data.strip())

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == 'a':
            self.links.append(attrs.get('href'))
        if attrs.get('id'):
            self.ids.append(attrs['id'])
        if tag == 'img':
            self.images.append(attrs.get('alt'))
        if tag == 'meta':
            self.meta.append(attrs)


def document(lang):
    original = (BASE / 'pages' / lang / 'index.html').read_text(encoding='utf-8')
    # Never regenerate navigation, translated copy, consent settings or link destinations.
    html = re.sub(r'<!-- Generated HTML:.*?-->',
                  '<!-- Generated by .github/tools/build-cad3d-home-performance.py from verified production source. -->',
                  original, count=1)
    for line in [
        '    <link rel="stylesheet" href="/_cad3d-site/assets/pannellum-2.5.7.css">\n',
        '    <script src="/_cad3d-site/assets/pannellum-2.5.7.js" defer></script>\n',
    ]:
        if html.count(line) != 1:
            raise ValueError('Production dependency changed: ' + line)
        html = html.replace(line, '', 1)
    html = html.replace(PREFIX + 'site.js?v=18', PREFIX + 'site-performance-v1.js')
    html = html.replace(PREFIX + 'media-v5.js', PREFIX + 'media-performance-v1.js')
    html = re.sub(r'(<link rel="preload"[^>]+ as="image")', r'\1 fetchpriority="high"', html)
    for before, after in IMAGES.items():
        html = html.replace(PREFIX + before, PREFIX + after)

    def responsive_bess(match):
        tag = match[0].replace(PREFIX + 'bess-ai-v11.webp', PREFIX + 'bess-preview-880-p1.webp')
        sources = ', '.join(PREFIX + f'bess-preview-{width}-p1.webp {width}w' for width in (480, 880, 1539))
        return tag.replace(' alt=', ' srcset="' + sources + '" sizes="(max-width:580px) calc(100vw - 48px), 46vw" alt=', 1)
    html, count = re.subn(r'<img\b[^>]+src="' + re.escape(PREFIX) + r'bess-ai-v11\.webp"[^>]*>', responsive_bess, html)
    if count != 1:
        raise ValueError('Expected exactly one home BESS preview')

    def thumbnail(match):
        return re.sub(r'width="2048" height="1347"', 'width="480" height="316"', match[0])
    html = re.sub(r'<img\b[^>]+src="' + re.escape(PREFIX) + r'interior-scene7-thumb-p1\.webp"[^>]*>', thumbnail, html)
    # The bath card occupies half the desktop grid; retain full-width sizing on mobile.
    def bath_sizes(match):
        return re.sub(r'sizes="[^"]*"', 'sizes="(max-width:580px) calc(100vw - 48px), 46vw"', match[0])
    html = re.sub(r'<img\b[^>]+src="' + re.escape(PREFIX) + r'bath-preview-880-p1\.webp"[^>]*>', bath_sizes, html)
    before, after = Content(), Content()
    before.feed(original)
    after.feed(html)
    for name in ('text', 'links', 'ids', 'images', 'meta'):
        if getattr(before, name) != getattr(after, name):
            raise ValueError('Unintended production content change: ' + lang + '/' + name)
    return html


def outputs():
    result = {}
    for name in ('site-performance-v1.js', 'media-performance-v1.js'):
        result[OUTPUT / 'assets' / name] = (WORK / 'home-performance-source' / name).read_bytes()
    for lang in ('it', 'en'):
        result[OUTPUT / 'pages' / lang / 'index.html'] = document(lang).encode('utf-8')
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    manifest = json.loads((BASE / 'capture.json').read_text())
    for entry in manifest:
        path = BASE / entry['path']
        if path.is_file() and hashlib.sha256(path.read_bytes()).hexdigest() != entry['sha256']:
            raise ValueError('Production baseline hash mismatch: ' + entry['path'])
    for path, content in outputs().items():
        if args.check:
            if not path.is_file() or path.read_bytes() != content:
                raise ValueError('Generated payload drift: ' + str(path.relative_to(ROOT)))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(content)
    print(('Verified' if args.check else 'Built') + ' two production home pages and two runtime modules.')


if __name__ == '__main__':
    main()
